const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function evaluate(obj) {
    return new Promise((resolve, reject) => {
      obj.evaluate((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  try {
    const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
    const zimFC = countries.filter(ee.Filter.eq('ADM0_NAME', 'Zimbabwe'));
    const zimCount = await evaluate(zimFC.size());
    if (!zimCount || zimCount === 0) {
      console.log('Zimbabwe geometry not found.');
      console.log('D');
      return;
    }
    const zim = zimFC.geometry();

    async function monthlyPrecipStats(startStr, endStr) {
      let start = startStr;
      let end = endStr;
      let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(start, end)
        .filterBounds(zim);
      let size = await evaluate(col.size());
      if (size === 0) {
        const s2 = ee.Date(start).advance(-3, 'day');
        const e2 = ee.Date(end).advance(3, 'day');
        let col2 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
          .filterDate(s2, e2)
          .filterBounds(zim);
        const size2 = await evaluate(col2.size());
        if (size2 === 0) {
          return { status: 'C1', images: 0, pixels: 0, mean: null };
        }
        col = col2;
        size = size2;
      }
      const sumImg = col.sum().clip(zim);
      const pix = await evaluate(
        sumImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: zim,
          scale: 5000,
          maxPixels: 1e10,
        }).get('precipitation')
      );
      if (!pix || pix === 0) {
        return { status: 'C2', images: size, pixels: pix || 0, mean: null };
      }
      const mean = await evaluate(
        sumImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: zim,
          scale: 5000,
          maxPixels: 1e10,
        }).get('precipitation')
      );
      if (mean === null || isNaN(mean) || mean < 0 || mean > 2000) {
        return { status: 'C3', images: size, pixels: pix, mean: mean };
      }
      return { status: 'OK', images: size, pixels: pix, mean: mean };
    }

    const feb2023 = await monthlyPrecipStats('2023-02-01', '2023-03-01');
    const feb2024 = await monthlyPrecipStats('2024-02-01', '2024-03-01');

    console.log('Dataset: CHIRPS Daily (mm/day), monthly sum and area-mean (mm)');
    console.log(`2023 Images: ${feb2023.images}`);
    console.log(`2023 Pixels: ${feb2023.pixels}`);
    if (feb2023.mean !== null && !isNaN(feb2023.mean)) {
      console.log(`2023 Mean(mm): ${feb2023.mean.toFixed(1)}`);
    } else {
      console.log('2023 Mean(mm): null');
    }
    console.log(`2024 Images: ${feb2024.images}`);
    console.log(`2024 Pixels: ${feb2024.pixels}`);
    if (feb2024.mean !== null && !isNaN(feb2024.mean)) {
      console.log(`2024 Mean(mm): ${feb2024.mean.toFixed(1)}`);
    } else {
      console.log('2024 Mean(mm): null');
    }

    // Handle failure cases
    if (feb2023.status === 'C1' || feb2024.status === 'C1') {
      console.log('C1');
      return;
    }
    if (feb2023.status === 'C2' || feb2024.status === 'C2') {
      console.log('C2');
      return;
    }
    if (feb2023.status === 'C3' || feb2024.status === 'C3') {
      console.log('C3');
      return;
    }

    const diff = feb2024.mean - feb2023.mean; // mm
    console.log(`Diff(mm, 2024-2023): ${diff.toFixed(1)}`);

    // Final answer: Decrease in 2024 vs 2023?
    const eps = 0.01;
    if (diff < -eps) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
